{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    min_sum = sum(seg['minimum'] for seg in segments)
    cap_sum = sum(seg['capacity'] for seg in segments)
    if budget < min_sum:
        raise ValueError("Budget below minimum sum")
    if budget > cap_sum:
        raise ValueError("Budget exceeds total capacity")
    alloc = [seg['minimum'] for seg in segments]
    remaining = budget - min_sum
    while remaining > 0:
        best_i = -1
        best_score = -1.0
        for i, seg in enumerate(segments):
            if alloc[i] < seg['capacity']:
                score = seg['importance'] / (alloc[i] + 1)
                if score > best_score:
                    best_score = score
                    best_i = i
        if best_i == -1:
            break
        alloc[best_i] += 1
        remaining -= 1
    by_name = {}
    for i, seg in enumerate(segments):
        by_name[seg['name']] = alloc[i]
    return {
        'allocations': alloc,
        'by_name': by_name,
        'total': budget
    }"
}
